import 'package:flutter/material.dart';import '../../core/money.dart';import '../../data/local_database.dart';import 'package:pdf/widgets.dart' as pw;import 'package:printing/printing.dart';
class InvoiceDetailScreen extends StatelessWidget{final int invoiceId;const InvoiceDetailScreen({super.key,required this.invoiceId});
Future<Map<String,Object?>> load()async{final db=await LocalDatabase.instance.database;final inv=(await db.query('invoices',where:'id=?',whereArgs:[invoiceId])).first;final lines=await db.query('invoice_items',where:'invoice_id=?',whereArgs:[invoiceId]);return {'invoice':inv,'items':lines};}
Future<void> printInvoice(Map<String,Object?> data)async{final doc=pw.Document();final inv=data['invoice'] as Map<String,Object?>;final lines=data['items'] as List<Map<String,Object?>>;doc.addPage(pw.Page(build:(ctx)=>pw.Directionality(textDirection:pw.TextDirection.rtl,child:pw.Column(crossAxisAlignment:pw.CrossAxisAlignment.stretch,children:[pw.Text('أرصد | ARSAD',style:pw.TextStyle(fontSize:20)),pw.Text('فاتورة رقم: ${inv['invoice_no']}'),pw.Text('التاريخ: ${inv['created_at']}'),pw.Divider(),...lines.map((x)=>pw.Text('${x['product_name']}  × ${x['quantity']}  = ${Money.format(x['line_total_halalas'] as int)}')),pw.Divider(),pw.Text('الإجمالي: ${Money.format(inv['total_halalas'] as int)}'),pw.Text('الدفع: ${inv['payment_method']=='cash'?'نقد':'شبكة'}')]))));await Printing.layoutPdf(onLayout:(_)=>doc.save());}
@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('تفاصيل الفاتورة')),body:FutureBuilder<Map<String,Object?>>(future:load(),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());final inv=s.data!['invoice'] as Map<String,Object?>;final lines=s.data!['items'] as List<Map<String,Object?>>;return ListView(padding:const EdgeInsets.all(16),children:[Text('فاتورة ${inv['invoice_no']}'),...lines.map((x)=>ListTile(title:Text(x['product_name'] as String),subtitle:Text('الكمية: ${x['quantity']}'),trailing:Text(Money.format(x['line_total_halalas'] as int)))),Text('الإجمالي: ${Money.format(inv['total_halalas'] as int)}'),FilledButton.icon(onPressed:()=>printInvoice(s.data!),icon:const Icon(Icons.print),label:const Text('طباعة / PDF'))]);}));}
